const {chromium}=require('playwright'),{pathToFileURL}=require('url'),path=require('path');
(async()=>{const b=await chromium.launch({args:['--no-sandbox']});try{const p=await b.newPage({viewport:{width:390,height:1000}}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.addInitScript(()=>{window.soundEvents=[];window.soundInstances=[];window.Audio=class{constructor(src){this.src=src;this.paused=true;soundInstances.push(this)}play(){this.paused=false;soundEvents.push(this.src);return Promise.resolve()}pause(){this.paused=true}};window.SpeechRecognition=class extends EventTarget{start(){this.dispatchEvent(new Event('start'))}abort(){this.dispatchEvent(new Event('end'))}stop(){this.dispatchEvent(new Event('end'))}}});await p.goto(process.env.ART_SITE_URL||pathToFileURL(path.resolve('index.html')).href);if(await p.evaluate(()=>soundEvents.length))throw Error('Effect autoplayed before gesture');async function toggleSound(){await p.click('#optionsButton');await p.click('#sfxToggle');await p.click('#optionsClose')}await p.click('#learningTab');await p.evaluate(()=>DEUTSCH_SFX.stop());if(!await p.evaluate(()=>DEUTSCH_SFX.play('clue')))throw Error('Unlocked effect did not play');await p.evaluate(()=>{window.voicePromise=speak('Hallo!',['audio/a001_ich.mp3'])});if(!await p.evaluate(()=>DEUTSCH_SFX.snapshot().speaking&&!DEUTSCH_SFX.play('click')&&soundInstances[0].paused))throw Error('Voice did not suppress effects');await p.evaluate(async()=>{const voice=soundInstances.at(-1);voice.paused=true;voice.onended();await voicePromise});if(!await p.evaluate(()=>!DEUTSCH_SFX.snapshot().speaking&&DEUTSCH_SFX.play('correct')))throw Error('Effect did not resume after voice');await p.evaluate(()=>{window.testMic=new SpeechRecognition();testMic.start()});if(!await p.evaluate(()=>DEUTSCH_SFX.snapshot().mics===1&&!DEUTSCH_SFX.play('seal')&&soundInstances[0].paused))throw Error('Microphone did not suppress effects');await p.evaluate(()=>testMic.abort());if(!await p.evaluate(()=>DEUTSCH_SFX.snapshot().mics===0&&DEUTSCH_SFX.play('incorrect')))throw Error('Microphone guard did not release');await toggleSound();if(await p.locator('#sfxToggle').getAttribute('aria-pressed')!=='false'||await p.evaluate(()=>DEUTSCH_SFX.play('voyage')))throw Error('Effects off failed');await p.reload();await p.click('#learningTab');if(await p.locator('#sfxToggle').getAttribute('aria-pressed')!=='false')throw Error('Mute lost after reload');await toggleSound();await p.evaluate(()=>{DEUTSCH_SFX.stop();DEUTSCH_SFX.play('lighthouse');setMode('words')});if(await p.evaluate(()=>DEUTSCH_SFX.snapshot().current!==null))throw Error('Navigation leaked sound');for(const width of [320,390,1280]){await p.setViewportSize({width,height:1000});if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1))throw Error('Effects settings overflow '+width)}await p.evaluate(()=>{document.documentElement.lang='en';DEUTSCH_JOURNEY.select(0)});await p.waitForFunction(()=>document.querySelector('#sfxToggle').textContent==='Effects: on');await toggleSound();await p.click('#profileButton');await p.fill('#profileAddInput','Effects child');await Promise.all([p.waitForEvent('load'),p.click('#profileAddForm button')]);if(await p.locator('#sfxToggle').getAttribute('aria-pressed')!=='true')throw Error('Mute leaked across profiles');const media=await b.newPage();await media.goto(process.env.ART_SITE_URL||pathToFileURL(path.resolve('index.html')).href);await media.evaluate(async()=>{const files=DEUTSCH_SFX.files;if(Object.keys(files).length!==7)throw Error('Not all seven effects');await Promise.all(Object.values(files).map(file=>new Promise((resolve,reject)=>{const a=new Audio('audio/sfx/20261025/'+file),timer=setTimeout(()=>reject(Error('Metadata timeout '+file)),10000);a.onloadedmetadata=()=>{clearTimeout(timer);a.duration>0&&a.duration<4?resolve():reject(Error('Bad duration '+file))};a.onerror=()=>{clearTimeout(timer);reject(Error('Undecodable effect '+file))};a.preload='metadata';a.load()})))});await media.close();if(errors.length)throw Error(errors.join(';'));console.log('PASS generated SFX: no pre-gesture autoplay, voice/microphone priority, stop/navigation, persisted mute, localization and responsive controls');}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)});
